fn ping() -> Int uses net or fail {
    let base = "https://api.example.com"
    let url = base + "/ping"
    return try fetch_status(url)
}

fn main() uses io, net {
    for i in 0 to 3 {
        check ping() {
            ok code {
                print(to_text(code))
            }
            fail why {
                print(why)
            }
        }
    }
}

